arguments.command:
cd /tmp && cat > TestNintStackalloc.cs << 'EOF'
using System;

class Program
{
    static void Main()
    {
        Span<nint> a = stackalloc nint[4];
        a[0] = 42;
        a[1] = nint.MaxValue;
        Console.WriteLine($"a[0] = {a[0]}, a[1] = {a[1]}, length = {a.Length}");

        Span<nuint> b = stackalloc nuint[3];
        b[0] = 123;
        Console.WriteLine($"b[0] = {b[0]}, length = {b.Length}");
    }
}
EOF
dotnet-script TestNintStackalloc.cs 2>/dev/null || dotnet run --project . 2>/dev/null || (echo "--- trying csc ---" && csc TestNintStackalloc.cs -out:TestNintStackalloc.exe && mono TestNintStackalloc.exe) || (echo "--- trying dotnet new ---" && mkdir -p /tmp/nint-test && cd /tmp/nint-test && dotnet new console --force -q && cp /tmp/TestNintStackalloc.cs Program.cs && dotnet run)

